-- 创建 AR/AW 地址通道。
local function make_ax_bundle(prefix, name)
    return ([[
        | valid      => valid
        | ready      => ready
        | bits_id    => id
        | bits_addr  => addr
        | bits_len   => len
        | bits_size  => size
        | bits_burst => burst
        | bits_cache => cache
        | bits_qos   => qos
    ]]):abdl {
        hier = DUT_HIER,
        prefix = prefix,
        name = name,
    }
end


-- 创建 W 写数据通道。
local function make_w_bundle(prefix, name)
    return ([[
        | valid     => valid
        | ready     => ready
        | bits_data => data
        | bits_strb => strb
        | bits_last => last
    ]]):abdl {
        hier = DUT_HIER,
        prefix = prefix,
        name = name,
    }
end


-- 创建 B 写响应通道。
local function make_b_bundle(prefix, name)
    return ([[
        | valid     => valid
        | ready     => ready
        | bits_id   => id
        | bits_resp => resp
    ]]):abdl {
        hier = DUT_HIER,
        prefix = prefix,
        name = name,
    }
end


-- 创建 R 读数据通道。
local function make_r_bundle(prefix, name)
    return ([[
        | valid     => valid
        | ready     => ready
        | bits_id   => id
        | bits_data => data
        | bits_resp => resp
        | bits_last => last
    ]]):abdl {
        hier = DUT_HIER,
        prefix = prefix,
        name = name,
    }
