local slv_ar = make_ax_bundle("io_slv_ar_", "SLV_AR")
local slv_r  = make_r_bundle("io_slv_r_", "SLV_R")
local slv_aw = make_ax_bundle("io_slv_aw_", "SLV_AW")
local slv_w  = make_w_bundle("io_slv_w_", "SLV_W")
local slv_b  = make_b_bundle("io_slv_b_", "SLV_B")


local pending_resps = {}

-- 测试阶段调用这个函数，为指定事务安排响应
function M.inject_resp(rule)
    assert(rule.resp >= 0 and rule.resp <= 3)
    pending_resps[#pending_resps + 1] = rule
end

local function resp_hook(ch, addr, id, len, size, burst)
    for i, rule in ipairs(pending_resps) do
        local matched =
            rule.ch == ch and
            (rule.addr  == nil or rule.addr  == addr) and
            (rule.id    == nil or rule.id    == id) and
            (rule.len   == nil or rule.len   == len) and
            (rule.size  == nil or rule.size  == size) and
            (rule.burst == nil or rule.burst == burst)

        if matched then
            table.remove(pending_resps, i)
            return rule.resp
        end
    end

    return 0 -- 未匹配的事务返回 OKAY
end


