local initialized = false

function M.initialize()
    -- 避免 testcase 重复调用时启动两份后台任务。
    if initialized then
        return
    end

    initialized = true
    axi_master:initialize()
    axi_memory:initialize()
end

-- AXI burst 类型编码。
local BURST_INCR = 1

-- AxiReorder 的数据宽度是 256 bit：
-- 256 bit = 32 byte = 2^5 byte，因此 AxSIZE = 5。
local AXI_SIZE_32_BYTES = 5

-- 256-bit 数据共有 32 个字节，每个字节对应一个 WSTRB bit。
-- 32 个 strobe bit 用 8 个十六进制字符表示。
local FULL_STRB_256 = "ffffffff"


-- 执行一笔单拍阻塞写。
--
-- 参数：
--   addr     ：写地址
--   data_hex ：256-bit 数据，用 64 个十六进制字符表示
--
-- 返回：
--   "Success" 或组件返回的错误字符串
function M.write_single(addr, data_hex)
    assert(
        type(data_hex) == "string",
        "write data must be a hexadecimal string"
    )

    assert(
        #data_hex == 64,
        string.format(
            "256-bit write data must contain 64 hex characters, got %d",
            #data_hex
        )
    )

    return axi_master:block_write(
        addr,
        BURST_INCR,

        -- AxLEN = 实际拍数 - 1。
        -- len=0 表示只有一拍。
        0,

        -- 每拍传输 2^5=32 字节。
        AXI_SIZE_32_BYTES,

        -- block_write 支持 burst，所以数据和 strobe 都用数组传入。
        -- 当前只有一拍，因此数组中各有一个元素。
        { data_hex },
        { FULL_STRB_256 }
    )
end

-- 执行一笔非阻塞写。
function M.noblock_write(addr, burst, len, size, data_hex_vec, strb_hex_vec, axid, qos, cache)

    local ticket = {
        done = false,
        result = nil,
        error = nil,
    }
    assert(type(addr) == "number", "addr must be a number")
    assert(type(burst) == "number", "burst must be a number")
    assert(type(len) == "number", "len must be a number")
    assert(type(size) == "number", "size must be a number")
    assert(type(data_hex_vec) == "table", "data_hex_vec must be a table")
    assert(type(strb_hex_vec) == "table", "strb_hex_vec must be a table")
    assert(type(axid) == "number", "axid must be a number")
    assert(len >= 0 and len <= 255,
        "len must be in range 0..255")
    assert(size >= 0 and size <= 5,
        "size must be in range 0..5")
    assert(
        axid >= 0 and axid < 4096,
        "axid must be in range 0..4095")

    assert(
        #data_hex_vec == len + 1,
        "write data beat count must equal len + 1"
    )

    assert(
        #strb_hex_vec == len + 1,
        "write strobe beat count must equal len + 1"
    )

    for beat, data in ipairs(data_hex_vec) do
        assert(type(data) == "string",
            string.format("data beat %d must be a string", beat))
        assert(#data == 64,
            string.format("data beat %d must contain 64 hex characters", beat))
        assert(data:match("^[0-9a-fA-F]+$"),
            string.format("data beat %d contains invalid hex characters", beat))
    end

    for beat, strb in ipairs(strb_hex_vec) do
        assert(type(strb) == "string",
            string.format("strb beat %d must be a string", beat))
        assert(#strb == 8,
            string.format("strb beat %d must contain 8 hex characters", beat))
        assert(strb:match("^[0-9a-fA-F]+$"),
            string.format("strb beat %d contains invalid hex characters", beat))
    end

    local ret = axi_master:write(
        addr,
        burst,

        -- len = 实际拍数 - 1。
        len,

        -- 每拍传输 2^size 字节。
        size,

        -- write() 使用数组描述每一拍数据和WSTRB。
        -- 数组元素数量必须等于 len + 1。
        data_hex_vec,
        strb_hex_vec,
        {
            axid = axid,
            qos = qos,
            cache = cache,
            finish_callback = function(task)

                ticket.result = {
                    addr = task.addr,
                    axid = task.axid,
                    len = task.len,
                    size = task.size,
                    burst = task.burst,
                }
                ticket.done = true
            end,
        }
    )
    if ret ~= "Success" then
        ticket.error = ret
    end
    return ret, ticket
end

-- 执行一笔单拍阻塞读。
--
-- 返回两个值：
--   ret      ："Success" 或错误字符串
--   data_hex ：读取到的 256-bit 十六进制字符串
function M.read_single(addr)
    local read_data_hex = nil

    local ret = axi_master:block_read(
        addr,
        BURST_INCR,
        0,
        AXI_SIZE_32_BYTES,

        {
            -- AXI4MasterV2 会在读事务结束时调用这个函数。
            -- task.read_data_hex_str_vec 中每个元素对应一拍 RDATA。
            finish_callback = function(task)
                read_data_hex = task.read_data_hex_str_vec[1]
            end,
        }
    )

    return ret, read_data_hex
end

-- 执行一笔非阻塞读。
--
-- 参数：
--   addr ：读地址
--   axid ：上游 AXI ARID
--
-- 返回：
--   ret    ：事务提交结果
--   ticket ：异步结果对象
function M.noblock_read(addr, burst, len, size, axid, qos, cache)

    assert(type(addr) == "number", "addr must be a number")
    assert(type(burst) == "number", "burst must be a number")
    assert(type(len) == "number", "len must be a number")
    assert(type(size) == "number", "size must be a number")
    assert(type(axid) == "number", "axid must be a number")

    assert(axid >= 0 and axid < 4096,
        "axid must be in range 0..4095")
    assert(len >= 0 and len <= 255,
        "len must be in range 0..255")
    assert(size >= 0 and size <= 5,
        "size must be in range 0..5 for a 256-bit bus")

    -- table 按引用传递。函数返回后，完成回调仍可更新其中的字段。
    local ticket = {
        done = false, -- 是否收到完整读响应
        data_vec = nil,   -- 读数据
        result = nil,   
        error = nil,
    }

    local ret = axi_master:read(
        addr,
        burst,
        len,
        size,

        {
            axid = axid,
            qos = qos,
            cache = cache,
            -- AXI4MasterV2 会在读事务结束时调用这个函数。
            -- task.read_data_hex_str_vec 中每个元素对应一拍 RDATA。
            finish_callback = function(task)
                --AXI4MasterV2 完成 callback 后会释放并清空 task。
                --AXI4MasterV2 会在 callback 后复用内部 task，
                --因此这里复制数据，避免 ticket 引用随后被清空的内部数组。
                local data_vec = {}

                for i, data in ipairs(task.read_data_hex_str_vec) do
                    data_vec[i] = data
                end

                -- 保存所有RDATA，方便后续检查；单拍读时只取第一个元素。
                ticket.data_vec = data_vec
                ticket.result = {
                    addr = task.addr,
                    axid = task.axid,
                    len = task.len,
                    size = task.size,
                    burst = task.burst,
                }

                -- done 最后赋值，保证看到 done=true 时其他结果已经有效。
                ticket.done = true
            end,
        }
    )
    if ret ~= "Success" then
        ticket.error = ret
    end
    return ret, ticket
end



function M.drive(v)

    assert(
        not initialized,
        "M.drive() cannot be used after AXI agents are initialized"
    )

    v = v or {}
    dut.io_mst_aw_valid:set(v.io_mst_aw_valid or 0)
    dut.io_mst_aw_bits_id:set(v.io_mst_aw_bits_id or 0)
    dut.io_mst_aw_bits_addr:set(v.io_mst_aw_bits_addr or 0)
    dut.io_mst_aw_bits_len:set(v.io_mst_aw_bits_len or 0)
    dut.io_mst_aw_bits_size:set(v.io_mst_aw_bits_size or 0)
    dut.io_mst_aw_bits_burst:set(v.io_mst_aw_bits_burst or 0)
    dut.io_mst_aw_bits_lock:set(v.io_mst_aw_bits_lock or 0)
    dut.io_mst_aw_bits_cache:set(v.io_mst_aw_bits_cache or 0)
    dut.io_mst_aw_bits_prot:set(v.io_mst_aw_bits_prot or 0)
    dut.io_mst_aw_bits_qos:set(v.io_mst_aw_bits_qos or 0)
    dut.io_mst_aw_bits_region:set(v.io_mst_aw_bits_region or 0)
    dut.io_mst_ar_valid:set(v.io_mst_ar_valid or 0)
    dut.io_mst_ar_bits_id:set(v.io_mst_ar_bits_id or 0)
    dut.io_mst_ar_bits_addr:set(v.io_mst_ar_bits_addr or 0)
    dut.io_mst_ar_bits_len:set(v.io_mst_ar_bits_len or 0)
    dut.io_mst_ar_bits_size:set(v.io_mst_ar_bits_size or 0)
    dut.io_mst_ar_bits_burst:set(v.io_mst_ar_bits_burst or 0)
